const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { loadConfig } = require('./config-loader.js');

function writeTempConfig(content) {
  const file = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'cfg-')), 'config.json');
  fs.writeFileSync(file, content);
  return file;
}

test('returns defaults when the file is missing', () => {
  const missing = path.join(os.tmpdir(), 'cfg-does-not-exist', 'config.json');
  const defaults = { port: 8080, host: 'localhost' };
  assert.deepStrictEqual(loadConfig(missing, defaults), { port: 8080, host: 'localhost' });
});

test('returns defaults when the file is missing and defaults omitted', () => {
  const missing = path.join(os.tmpdir(), 'cfg-does-not-exist', 'config.json');
  assert.deepStrictEqual(loadConfig(missing), {});
});

test('merges defaults with user values', () => {
  const file = writeTempConfig('{"port":3000}');
  const merged = loadConfig(file, { port: 8080, host: 'localhost', debug: false });
  assert.deepStrictEqual(merged, { port: 3000, host: 'localhost', debug: false });
});

test('merges nested objects instead of overwriting them', () => {
  const file = writeTempConfig('{"db":{"port":5432}}');
  const merged = loadConfig(file, { db: { host: 'localhost', port: 3306, pool: 10 } });
  assert.deepStrictEqual(merged, { db: { host: 'localhost', port: 5432, pool: 10 } });
});

test('preserves user values when they conflict with defaults', () => {
  const file = writeTempConfig('{"port":3000,"host":"example.com"}');
  const merged = loadConfig(file, { port: 8080, host: 'localhost', debug: true });
  assert.deepStrictEqual(merged, { port: 3000, host: 'example.com', debug: true });
});

test('user value of a different type replaces the default entirely', () => {
  const file = writeTempConfig('{"port":"8080","retries":"disabled"}');
  const merged = loadConfig(file, { port: 3000, retries: { max: 3 } });
  assert.deepStrictEqual(merged, { port: '8080', retries: 'disabled' });
});

test('user arrays and null replace defaults without merging', () => {
  const file = writeTempConfig('{"tags":["a"],"timeout":null}');
  const merged = loadConfig(file, { tags: ['z'], timeout: 5000, keep: 1 });
  assert.deepStrictEqual(merged, { tags: ['a'], timeout: null, keep: 1 });
});

test('invalid JSON still throws SyntaxError', () => {
  const file = writeTempConfig('{ not json');
  assert.throws(() => loadConfig(file), SyntaxError);
});
